// Command kvtemme generates zz_kvTemme_coeffs.go: the Taylor coefficients of
// 1/Gamma(1+u) = sum_m B_m u^m, from which kv_temme_fast.go forms the two even
// functions of Temme's series (DLMF 10.31 and Temme 1975),
//
//	g2(w) = (1/Gamma(1-u) + 1/Gamma(1+u))/2          = sum_j  B_(2j)   w^j,
//	g1(w) = (1/Gamma(1-u) - 1/Gamma(1+u))/(2u)       = - sum_j B_(2j+1) w^j,  w = u^2,
//
// with no division by u and no subtraction of nearly equal numbers: the limit
// u -> 0 is the constant term (g1(0) = -gamma, g2(0) = 1).
//
// B_m is computed in 300-bit arithmetic from
//
//	1/Gamma(1+u) = exp(gamma u - sum_(n>=2) (-1)^n zeta(n) u^n / n)   (DLMF 5.7.3, 5.7.4 via
//	               ln Gamma(1+u) = -gamma u + sum_(n>=2) zeta(n) (-u)^n / n),
//	B_0 = 1,  B_m = (1/m) sum_(n=1..m) n s_n B_(m-n),  n s_1 = gamma,  n s_n = -(-1)^n zeta(n),
//
// zeta(n) by Euler-Maclaurin summation from N = 100 with 40 Bernoulli terms
// (error below 2^-200), gamma = 1 - sum_(k>=2) (zeta(k) - 1)/k (k <= 170).
// Each coefficient is stored as a double-double (hi + lo) where the series needs
// it and as a float64 beyond. The generator shares nothing with the package; the
// test TestKvTemmeGammaSeries holds the table against the package's math/big
// oracle for ln Gamma.
//
//	go run ./testdata/gen/kvtemme > zz_kvTemme_coeffs.go
//	go run ./testdata/gen/kvtemme -report
package main

import (
	"flag"
	"fmt"
	"math"
	"math/big"
	"os"
)

const (
	prec  = 300
	emN   = 100 // Euler-Maclaurin start
	emJ   = 40  // Bernoulli terms
	gamK  = 170 // terms of the series for gamma
	maxM  = 64  // B_0 .. B_(maxM-1) computed
	outJ  = 14  // coefficients per function in the table
	ddCut = 4   // the first ddCut coefficients of each function as hi + lo
)

func bf() *big.Float { return new(big.Float).SetPrec(prec) }

func bernoulli(n int) []*big.Rat {
	b := make([]*big.Rat, n+1)
	b[0] = big.NewRat(1, 1)
	for m := 1; m <= n; m++ {
		s := new(big.Rat)
		binom := big.NewInt(1) // C(m+1, 0)
		for k := 0; k < m; k++ {
			t := new(big.Rat).SetInt(binom)
			s.Add(s, t.Mul(t, b[k]))
			binom.Mul(binom, big.NewInt(int64(m+1-k)))
			binom.Quo(binom, big.NewInt(int64(k+1)))
		}
		b[m] = s.Neg(s.Quo(s, big.NewRat(int64(m+1), 1)))
	}
	return b
}

func fact(n int) *big.Int {
	f := big.NewInt(1)
	for i := 2; i <= n; i++ {
		f.Mul(f, big.NewInt(int64(i)))
	}
	return f
}

// zeta returns zeta(n), n >= 2.
func zeta(n int, bern []*big.Rat) *big.Float {
	s := bf()
	for k := 1; k < emN; k++ {
		t := bf().SetInt64(1)
		kk := bf().SetInt64(int64(k))
		for i := 0; i < n; i++ {
			t.Quo(t, kk)
		}
		s.Add(s, t)
	}
	nn := bf().SetInt64(emN)
	npow := bf().SetInt64(1) // N^-n
	for i := 0; i < n; i++ {
		npow.Quo(npow, nn)
	}
	// N^(1-n)/(n-1) + N^-n/2
	t := bf().Mul(npow, nn)
	t.Quo(t, bf().SetInt64(int64(n-1)))
	s.Add(s, t)
	s.Add(s, bf().Quo(npow, bf().SetInt64(2)))
	// sum_j B_2j/(2j)! n(n+1)...(n+2j-2) N^(-n-2j+1)
	rise := bf().SetInt64(1)
	pw := bf().Quo(npow, nn) // N^(-n-1)
	n2 := bf().Mul(nn, nn)
	for j := 1; j <= emJ; j++ {
		// rise = n (n+1) ... (n+2j-2)
		if j == 1 {
			rise.SetInt64(int64(n))
		} else {
			rise.Mul(rise, bf().SetInt64(int64(n+2*j-3)))
			rise.Mul(rise, bf().SetInt64(int64(n+2*j-2)))
		}
		c := bf().SetRat(bern[2*j])
		c.Quo(c, bf().SetInt(fact(2*j)))
		c.Mul(c, rise)
		c.Mul(c, pw)
		s.Add(s, c)
		pw.Quo(pw, n2)
	}
	return s
}

func split(x *big.Float) (hi, lo float64) {
	hi, _ = x.Float64()
	r := bf().Sub(x, bf().SetFloat64(hi))
	lo, _ = r.Float64()
	return
}

func main() {
	report := flag.Bool("report", false, "print the coefficients and the size of the terms at u = 1/2")
	flag.Parse()
	bern := bernoulli(2*emJ + 2)
	zs := make([]*big.Float, gamK+1)
	for n := 2; n <= gamK; n++ {
		zs[n] = zeta(n, bern)
	}
	gamma := bf().SetInt64(1)
	one := bf().SetInt64(1)
	for k := 2; k <= gamK; k++ {
		t := bf().Sub(zs[k], one)
		t.Quo(t, bf().SetInt64(int64(k)))
		gamma.Sub(gamma, t)
	}
	B := make([]*big.Float, maxM)
	B[0] = bf().SetInt64(1)
	for m := 1; m < maxM; m++ {
		s := bf()
		for n := 1; n <= m; n++ {
			var ns *big.Float
			if n == 1 {
				ns = gamma
			} else {
				ns = bf().Set(zs[n])
				if n%2 == 0 {
					ns.Neg(ns)
				}
			}
			s.Add(s, bf().Mul(ns, B[m-n]))
		}
		B[m] = s.Quo(s, bf().SetInt64(int64(m)))
	}
	if *report {
		fmt.Printf("gamma = %s\n", gamma.Text('g', 40))
		for m := 0; m < maxM; m++ {
			f, _ := B[m].Float64()
			fmt.Printf("B_%-2d = %+.17e   |B_m| 2^-m = %.3e\n", m, f, math.Abs(f)*math.Pow(2, -float64(m)))
		}
		return
	}
	w := os.Stdout
	fmt.Fprintln(w, "// Code generated by testdata/gen/kvtemme; DO NOT EDIT.")
	fmt.Fprintln(w)
	fmt.Fprintln(w, "package special")
	fmt.Fprintln(w)
	fmt.Fprintln(w, "// Taylor coefficients of g2(w) = (1/Gamma(1-u) + 1/Gamma(1+u))/2 and g1(w) =")
	fmt.Fprintln(w, "// (1/Gamma(1-u) - 1/Gamma(1+u))/(2u), w = u^2 (the functions of Temme's series for")
	fmt.Fprintln(w, "// K_u, DLMF 10.31): g2 = sum kvTemmeG2[j] w^j, g1 = sum kvTemmeG1[j] w^j, from")
	fmt.Fprintln(w, "// 1/Gamma(1+u) = sum B_m u^m (kvtemme/main.go, 300-bit arithmetic): G2[j] =")
	fmt.Fprintln(w, "// B_(2j), G1[j] = -B_(2j+1). The first kvTemmeGammaDD of each as hi + lo, the")
	fmt.Fprintln(w, "// rest as float64 (hi, lo = 0).")
	fmt.Fprintf(w, "const kvTemmeGammaDD = %d\n\n", ddCut)
	fmt.Fprintf(w, "const kvTemmeGammaTerms = %d\n\n", outJ)
	for _, g := range []struct {
		name string
		idx  func(j int) int
		neg  bool
	}{{"kvTemmeG2", func(j int) int { return 2 * j }, false}, {"kvTemmeG1", func(j int) int { return 2*j + 1 }, true}} {
		fmt.Fprintf(w, "var %s = [%d][2]float64{\n", g.name, outJ)
		for j := 0; j < outJ; j++ {
			c := bf().Set(B[g.idx(j)])
			if g.neg {
				c.Neg(c)
			}
			hi, lo := split(c)
			if j >= ddCut {
				lo = 0
			}
			fmt.Fprintf(w, "\t{%v, %v},\n", hi, lo)
		}
		fmt.Fprint(w, "}\n")
		if g.neg {
			continue
		}
		fmt.Fprintln(w)
	}
}
